import{_ as a,o as t,c as o,a0 as s}from"./chunks/framework.CNXp-E7Q.js";const u=JSON.parse('{"title":"Flow: a push becomes a commit status","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/flow.md","filePath":"explanation/flow.md"}'),n={name:"explanation/flow.md"};function r(d,e,c,i,l,h){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="flow-a-push-becomes-a-commit-status" tabindex="-1">Flow: a push becomes a commit status <a class="header-anchor" href="#flow-a-push-becomes-a-commit-status" aria-label="Permalink to &quot;Flow: a push becomes a commit status&quot;">​</a></h1><p>One end-to-end narrative of bupha&#39;s flagship operation — what actually happens between <code>git push</code> and the <code>ci/bupha</code> check going green. Two deployment shapes share the same engine: the standalone <code>host</code> watcher (dev/single-box) and the fleet <code>worker</code> (entity plane); the ingest→queue→worktree→status core is identical.</p><h2 id="_1-ingest-—-the-webhook-arrives" tabindex="-1">1. Ingest — the webhook arrives <a class="header-anchor" href="#_1-ingest-—-the-webhook-arrives" aria-label="Permalink to &quot;1. Ingest — the webhook arrives&quot;">​</a></h2><p>GitHub POSTs a signed delivery to the bundle&#39;s public URL (<code>provider.ingress</code>, fronted by your tunnel — or, in production, to the peregrin campaign listener which normalizes it into a <code>ci-job</code> entity instead). The pipeline, byte-stable:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /hook → path check → body ≤ 2 MiB → repo hint (untrusted peek,</span></span>
<span class="line"><span>  unwatched repo 404s) → HMAC-SHA256 verify (per-repo secret_env,</span></span>
<span class="line"><span>  constant-time) → delivery-id dedup (10k ring) → parse (skip</span></span>
<span class="line"><span>  deletes/zero-sha) → route (git_ref → matching job queues, forge-</span></span>
<span class="line"><span>  attested sender vs access policy) → enqueue</span></span></code></pre></div><p>A push to <code>main</code> fans out into every <code>[[repo]]</code>/<code>[[repo.jobs]]</code> entry watching that ref — a gate job and a docs-deploy job are independent queues.</p><h2 id="_2-queue-—-latest-wins-or-bounded-fifo" tabindex="-1">2. Queue — latest-wins or bounded FIFO <a class="header-anchor" href="#_2-queue-—-latest-wins-or-bounded-fifo" aria-label="Permalink to &quot;2. Queue — latest-wins or bounded FIFO&quot;">​</a></h2><p>Each job queue applies its policy:</p><ul><li><code>latest</code> (default): one pending sha; a new push supersedes it and <code>cancel_running</code> may kill the in-flight run.</li><li><code>all</code>: bounded FIFO (32); every push runs, oldest evicted past cap.</li></ul><p>Accepted work persists via <code>QueueStore</code> (dev <code>json</code> file; the <code>ci-job</code> entity plane in fleets). On restart, an interrupted <code>running</code> sha re-queues at the front.</p><h2 id="_3-worktree-—-isolated-always-at-the-pushed-sha" tabindex="-1">3. Worktree — isolated, always at the pushed sha <a class="header-anchor" href="#_3-worktree-—-isolated-always-at-the-pushed-sha" aria-label="Permalink to &quot;3. Worktree — isolated, always at the pushed sha&quot;">​</a></h2><p>The global worker serializes runs across repos (one box, bounded resources — deliberate). It fetches, then checks out a <strong>detached worktree</strong> at <code>&lt;base&gt;-&lt;repo&gt;[-&lt;job&gt;]-&lt;sha12&gt;</code> — never a shared, dirty checkout. Fork-PR jobs may fetch <code>cloneUrl</code>/<code>headRef</code> first.</p><h2 id="_4-run-—-the-runner-executes" tabindex="-1">4. Run — the runner executes <a class="header-anchor" href="#_4-run-—-the-runner-executes" aria-label="Permalink to &quot;4. Run — the runner executes&quot;">​</a></h2><p>The job&#39;s <code>runner.kind</code> decides what &quot;run&quot; means:</p><ul><li><code>shell</code>/<code>script</code> — <code>bash -c &lt;cmd&gt;</code> in the worktree</li><li><code>gha</code> — parse <code>.github/workflows</code> at the sha, execute the <code>on.push</code> subset (needs-DAG, matrix legs in parallel worktrees)</li><li><code>dagger</code> — <code>dagger call &lt;fn&gt;</code> per job</li><li><code>container</code>/<code>ssh</code>/<code>http</code> — isolation and remote execution</li></ul><p>Secrets reach the runner by name only (<code>env://</code>, cuora refs) — tokens never touch argv. Matrix legs and parallel jobs each get a private worktree; <code>$GITHUB_*</code> file commands are honored in the <code>gha</code> dialect.</p><h2 id="_5-status-—-honest-verdicts" tabindex="-1">5. Status — honest verdicts <a class="header-anchor" href="#_5-status-—-honest-verdicts" aria-label="Permalink to &quot;5. Status — honest verdicts&quot;">​</a></h2><p>Terminal states post commit statuses:</p><ul><li><code>success</code>/<code>failure</code> — the run&#39;s verdict under <code>ci/bupha</code> (or <code>[status].context</code>); the <code>gha</code> dialect additionally posts per-job detail under <code>&lt;context&gt;/&lt;workflow&gt;/&lt;job&gt;</code>.</li><li><code>error</code> — honest failure (superseded sha, cancelled run, spawn error). A killed run reports &quot;cancelled (superseded)&quot;, not failure.</li></ul><p>Step 6 is yours: merge on green, or wire <code>action.yml</code>&#39;s <code>mode: wait</code> into a GHA workflow as a required check.</p><h2 id="the-shape-underneath" tabindex="-1">The shape underneath <a class="header-anchor" href="#the-shape-underneath" aria-label="Permalink to &quot;The shape underneath&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push ──► signed webhook ──► Source/Trigger ──► queue (policy)</span></span>
<span class="line"><span>                                                    │</span></span>
<span class="line"><span>                              ci-job entity ◄───────┤ fleet mode</span></span>
<span class="line"><span>                                                    ▼</span></span>
<span class="line"><span>                                        worktree @ sha ──► runner ──► status</span></span></code></pre></div><p>See <a href="./architecture.html">architecture</a> for the port/adapter map, <a href="./../how-to/distributed-runners.html">distributed runners</a> for the fleet path, and <a href="./concepts.html">concepts</a> for the vocabulary.</p>`,23)])])}const b=a(n,[["render",r]]);export{u as __pageData,b as default};
